const axios = require('axios');

async function scrapeTikTok(url) {
  try {
    const response = await axios.post('https://tiktokdownloaderr.id/api/downloader.php', {
      url: url
    });
    return response.data;
  } catch (error) {
    console.error('Error scraping TikTok:', error);
    throw error;
  }
}

